/* Extra controls are part of the same per-character draft and Save action. */
(() => {
 const el=id=>document.getElementById(id),copy=v=>structuredClone(v);
 const defaults={refiner:{mode:'inherit',targets:['portrait','cg'],checkpoint:'',switch:.8},hires:{mode:'inherit',targets:['portrait','cg'],scale:1.5,upscaler:'Lanczos',steps:20,denoise:.35,sampler:'',cfg:6},adetailer:{mode:'inherit',targets:['portrait','cg'],passes:[]}},adDefault={model:'',follow:true,prompt:'',negative:'',confidence:.3,denoise:.4,mask_blur:4,dilate:4,padding:32,only_masked:true,steps:28,cfg:7,sampler:'',parameters:{}};
 let data=null,styles=[],options=copy(defaults);
 const notify=()=>document.dispatchEvent(new Event('sd-options-input'));
 function element(tag,text,cls){const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n;}
 function choices(category){return data.resources.filter(r=>r.selectable&&r.category===category&&r.installations.includes(data.config.installation)).sort((a,b)=>a.name.localeCompare(b.name)).map(r=>[r.id,r.name+' · '+(r.base||'未知架構')]);}
 function field(parent,obj,key,label,type='text',values=[],min=null,max=null,step=null){const wrap=element('label',label),input=element(type==='select'?'select':type==='textarea'?'textarea':'input');input.dataset.sdField=key;input.setAttribute('aria-label',label);if(type==='select'){for(const [value,title] of values){const o=element('option',title);o.value=value;input.append(o);}if(obj[key]&&![...input.options].some(o=>o.value===String(obj[key]))){const o=element('option','先前選定的資源（目前未找到）');o.value=obj[key];o.disabled=true;input.append(o);}}else if(type==='textarea'){input.rows=3;input.maxLength=key==='parameters'?6000:1600;}else{input.type=type;if(min!==null)input.min=min;if(max!==null)input.max=max;if(step!==null)input.step=step;}if(type==='checkbox')input.checked=obj[key];else input.value=obj[key]??'';input.addEventListener('input',()=>{obj[key]=type==='checkbox'?input.checked:input.value;notify();});wrap.append(input);parent.append(wrap);return input;}
 function action(parent,label,fn){const b=element('button',label);b.type='button';b.onclick=fn;parent.append(b);return b;}
 function reorder(parent,items,index,paint){const bar=element('div',null,'studio-actions');action(bar,'移除',()=>{items.splice(index,1);paint();notify();});const up=action(bar,'往上',()=>{[items[index-1],items[index]]=[items[index],items[index-1]];paint();notify();});up.disabled=index===0;const down=action(bar,'往下',()=>{[items[index+1],items[index]]=[items[index],items[index+1]];paint();notify();});down.disabled=index===items.length-1;parent.append(bar);}
 function paintStyles(){const box=el('atelier-extra-styles');box.replaceChildren();styles.forEach((p,i)=>{const card=element('section',null,'sd-option-card'),grid=element('div',null,'control-pair');card.append(element('h4','畫風 LoRA '+(i+2)));field(grid,p,'enabled','啟用此畫風','checkbox');field(grid,p,'lora','額外畫風 LoRA','select',[['','請選畫風 LoRA'],...choices('lora')]);field(grid,p,'weight','畫風 LoRA 權重','number',[],0,1.5,.05);field(grid,p,'trigger','畫風觸發詞');card.append(grid);reorder(card,styles,i,paintStyles);box.append(card);});el('atelier-add-style').disabled=styles.length>=7;}
 function header(parent,obj){field(parent,obj,'mode','使用方式','select',[['inherit','沿用原生模板'],['on','使用此人物設定'],['off','明確關閉']]);const group=element('fieldset');group.append(element('legend','套用生成用途'));for(const [kind,label] of [['portrait','立繪差分'],['pixel','行走圖'],['cg','CG 插圖']]){const wrap=element('label',label),box=element('input');box.type='checkbox';box.checked=obj.targets.includes(kind);box.onchange=()=>{obj.targets=box.checked?[...obj.targets,kind]:obj.targets.filter(k=>k!==kind);notify();};wrap.append(box);group.append(wrap);}parent.append(group);}
 function paintAD(){const box=el('atelier-ad-passes');box.replaceChildren();options.adetailer.passes.forEach((a,i)=>{const card=element('details',null,'sd-option-card');card.open=i===0;card.append(element('summary','修補順序 '+(i+1)));const grid=element('div',null,'control-pair');field(grid,a,'model','ADetailer 偵測器','select',[['','請選偵測器'],...(data.service.adetailer_models||[]).map(n=>[n,n])]);field(grid,a,'follow','跟隨角色身份與表情','checkbox');field(grid,a,'prompt','修補正向補充','textarea');field(grid,a,'negative','修補負向提示','textarea');for(const [key,label,min,max,step] of [['confidence','偵測信心門檻',0,1,.05],['denoise','修補重繪幅度',0,1,.05],['mask_blur','遮罩模糊',0,64,1],['dilate','遮罩膨脹／收縮',-128,128,1],['padding','遮罩外留白',0,256,1],['steps','修補步數',1,80,1],['cfg','修補 CFG',1,20,.5]])field(grid,a,key,label,'number',[],min,max,step);field(grid,a,'only_masked','只修補遮罩區域','checkbox');field(grid,a,'sampler','修補採樣器','select',[['','沿用主要採樣器'],...(data.service.samplers||[]).map(n=>[n,n])]);card.append(grid);const extra=element('details');extra.append(element('summary','ADetailer 其他參數 JSON'));field(extra,a,'parameters','其他修補參數','textarea');extra.append(element('p','可補充局部尺寸、模型、VAE、排程器、ControlNet 等原生參數；表單已管理的欄位不可重複。','studio-hint'));card.append(extra);reorder(card,options.adetailer.passes,i,paintAD);box.append(card);});el('atelier-add-ad').disabled=options.adetailer.passes.length>=Math.min(4,data.service.adetailer_slots||4);}
 function paintOptions(){for(const [name,title] of [['refiner','Refiner'],['hires','Hires.fix'],['adetailer','ADetailer']]){const box=el('atelier-option-'+name);box.replaceChildren();header(box,options[name]);const grid=element('div',null,'control-pair');if(name==='refiner'){field(grid,options.refiner,'checkpoint','Refiner 模型','select',[['','請選 Refiner 模型'],...choices('checkpoint')]);field(grid,options.refiner,'switch','Refiner 切換比例','number',[],.01,.99,.05);}if(name==='hires'){field(grid,options.hires,'upscaler','高解析放大器','select',[['','請選放大器'],...(data.service.upscalers||[]).map(n=>[n,n])]);field(grid,options.hires,'sampler','高解析採樣器','select',[['','沿用主要採樣器'],...(data.service.samplers||[]).map(n=>[n,n])]);for(const [key,label,min,max,step] of [['scale','放大倍率',1,2,.1],['steps','高解析步數',1,80,1],['denoise','高解析重繪幅度',0,1,.05],['cfg','高解析 CFG',1,20,.5]])field(grid,options.hires,key,label,'number',[],min,max,step);}box.append(grid);}paintAD();}
 function load(d,profile,draft){data=d;styles=copy(draft?.style_loras??profile.style_loras??[]);options=copy(defaults);for(const name of Object.keys(defaults))options[name]={...options[name],...copy((draft?.render_options??profile.render_options??{})[name]||{})};for(const a of options.adetailer.passes){for(const [k,v] of Object.entries(adDefault))if(a[k]===undefined)a[k]=copy(v);if(typeof a.parameters!=='string')a.parameters=JSON.stringify(a.parameters,null,2);}paintStyles();paintOptions();el('atelier-capabilities-note').textContent=data.config.backend==='a1111'?('本機功能：'+(data.service.adetailer_models?.length||0)+' 個偵測器 · '+(data.service.upscalers?.length||0)+' 個本機放大器。'): 'Refiner／ADetailer／Hires.fix 面板適用 WebUI／Forge；ComfyUI 請沿用原生工作流。';}
 function read(){const result=snapshot();for(const s of result.style_loras)s.weight=Number(s.weight);for(const key of ['switch'])result.render_options.refiner[key]=Number(result.render_options.refiner[key]);for(const key of ['scale','steps','denoise','cfg'])result.render_options.hires[key]=Number(result.render_options.hires[key]);for(const a of result.render_options.adetailer.passes){for(const key of ['confidence','denoise','mask_blur','dilate','padding','steps','cfg'])a[key]=Number(a[key]);try{a.parameters=JSON.parse(a.parameters||'{}');}catch{throw Error('ADetailer 其他參數 JSON 格式不正確；人物草稿保留。');}}return result;}
 function snapshot(){return {style_loras:copy(styles),render_options:copy(options)};}
 el('atelier-add-style').onclick=()=>{if(styles.length<7){styles.push({lora:'',weight:.8,trigger:'',enabled:true});paintStyles();notify();}};
 el('atelier-add-ad').onclick=()=>{if(options.adetailer.passes.length<Math.min(4,data.service.adetailer_slots||4)){const a=copy(adDefault);a.parameters='{}';options.adetailer.passes.push(a);paintAD();notify();}};
 window.CharacterSDOptions={load,read,snapshot,dirty(profile){const actual=read(),old={style_loras:profile.style_loras||[],render_options:copy(defaults)};for(const n of Object.keys(defaults))old.render_options[n]={...old.render_options[n],...copy(profile.render_options?.[n]||{})};const stable=v=>v&&typeof v==='object'&&!Array.isArray(v)?'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+stable(v[k])).join(',')+'}':Array.isArray(v)?'['+v.map(stable).join(',')+']':JSON.stringify(v);return stable(actual)!==stable(old);}};
})();
